1	#!/usr/bin/env bun
2	/**
3	 * check_sub_issue_closure.ts — Determine whether a just-closed issue is an
4	 * Atomaton sub-issue. If it is, the aggregation gate is left to decide whether its
5	 * parent is ready; this script answers only "is there a parent, and what is it".
6	 *
7	 * ## Why it asks GitHub rather than reading the event
8	 *
9	 * It used to take the parent from the `<!-- atomaton:parent=N -->` tag in the closed
10	 * issue's body, which the webhook payload already carries — free, and wrong for the
11	 * same reason the tag is gone everywhere else: it recorded the parent at creation and
12	 * nothing rewrote it, so a sub-issue re-parented in the web UI aggregated under the
13	 * issue it used to be under. One request buys the answer the rest of the system uses.
14	 *
15	 * A parent that could not be READ is not a parent that is absent. Saying
16	 * `is_sub_issue=false` there would skip the aggregation silently, and nothing else
17	 * would notice a parent that is never re-invoked — so this fails instead.
18	 *
19	 * ## Why it no longer asks whether a merged PR closed this issue
20	 *
21	 * It used to, and used the answer to skip the whole aggregation: "a merged PR
22	 * links this sub-issue, so atomaton-pr-closed.wac.ts already handled the parent".
23	 * That is a fact about the SUB-ISSUE standing in for a fact about the PARENT, and
24	 * the two are different questions at different levels of the tree. A pull request
25	 * that closes a sub-issue says the sub-issue's work was delivered; it says nothing
26	 * about whether the sub-issue's parent was ever aggregated.
27	 *
28	 * The inference was wrong in the direction that loses work, and measurably so. An
29	 * agent's merge (`merge_pr`, permitted by the shipped `merge.policy: auto`) runs as
30	 * GITHUB_TOKEN, and GitHub raises no event cascade for its own token's actions — so
31	 * atomaton-pr-closed never fires for that merge, while the merged PR still appears
32	 * in `closedByPullRequestsReferences`. The guard answered `closed_via_pr=true` and
33	 * skipped a close whose primary path had not run at all; the skip left no comment,
34	 * no failure, and a green workflow — the same silent-loss shape as #143. The
35	 * measured case and its numbers are #150's.
36	 *
37	 * The duplicate it was preventing is real but belongs one level up: two paths
38	 * aggregating the SAME parent node. `aggregation.ts`'s `atomaton:aggregated` marker
39	 * already answers that where the identity actually lives — on the parent's own
40	 * thread — and makes the second caller a no-op. A guard one level down cannot answer
41	 * it, which is why it was both unreliable and unnecessary. The sweep this is one
42	 * instance of is #149; the guard's removal is #150.
43	 *
44	 * Env: CLOSED_NUM, OWNER, REPO
45	 * Writes to $GITHUB_OUTPUT: is_sub_issue, parent_number
46	 */
47	import { appendFileSync } from "node:fs";
48	import { parentIssueOf } from "../../adapters/github/parent-issue.ts";
49	import { defineScript } from "./lib/script-ref.ts";
50	
51	export const ref = defineScript(import.meta.url);
52	
53	function main(): void {
54	  const closedNum = process.env.CLOSED_NUM ?? "";
55	  const owner = process.env.OWNER ?? "";
56	  const repo = process.env.REPO ?? "";
57	  const githubOutput = process.env.GITHUB_OUTPUT;
58	
59	  const found = parentIssueOf(`${owner}/${repo}`, Number(closedNum));
60	  if (!found.known) {
61	    console.error(
62	      `::error::Could not tell whether #${closedNum} is a sub-issue (${found.why}), so nothing was aggregated. ` +
63	        "Its parent will not be re-invoked until someone does it by hand.",
64	    );
65	    process.exit(1);
66	  }
67	  const parent = found.parent || undefined;
68	
69	  if (parent === undefined) {
70	    if (githubOutput) appendFileSync(githubOutput, "is_sub_issue=false\n");
71	    return;
72	  }
73	
74	  console.error(`Sub-issue #${closedNum} closed — parent #${parent}`);
75	
76	  if (githubOutput) {
77	    appendFileSync(githubOutput, ["is_sub_issue=true", `parent_number=${parent}`].join("\n") + "\n");
78	  }
79	}
80	
81	if (import.meta.main) main();

