157	/** True when the atomaton was not started and something is left undone. */
158	export function needsAttention(result: DispatchGateResult): boolean {
159	  return (
160	    result.kind === "dispatch-failed" ||
161	    result.kind === "undetermined" ||
162	    result.kind === "parent-closed" ||
163	    result.kind === "parent-busy"
164	  );
