167	/**
168	 * The one sentence a gate result deserves in a run log.
169	 *
170	 * Both callers used to print the same hedge -- "another caller already handled
171	 * this completion, or the dispatch failed" -- because the old return type could
172	 * not tell those apart. It listed two causes where there were three, in two
173	 * files, and neither noticed. A sentence duplicated verbatim across call sites
174	 * is a return type asking to be a union.
175	 */
176	export function describeGateResult(result: DispatchGateResult, closedNum: number, parent?: number): string {
177	  // `parent` is optional because the in-run callers do not know it: a close
178	  // reaches the gate through the sub-issue's own link. Named as "the parent"
179	  // there rather than printed as `#0`, which would be a number that identifies
180	  // a different thing.
181	  const which = parent === undefined ? "the parent issue" : `#${parent}`;
182	  switch (result.kind) {
183	    case "not-tracked":
184	      return `#${closedNum} is not a tracked sub-issue; nothing to aggregate.`;
185	    case "waiting":
186	      return `${result.remaining} sibling(s) of ${which} still open. No action needed.`;
187	    case "already-aggregated":
188	      return `Another caller already aggregated #${closedNum}. Nothing to do -- this is the normal race.`;
189	    case "dispatched":
190	      return `All sub-tasks of ${which} complete. The parent's agent was re-invoked.`;
191	    case "dispatch-failed":
192	      return (
193	        `All sub-tasks of ${which} complete, but the dispatch FAILED. ` +
194	        `The aggregation marker was removed, so closing a sub-issue again retries it -- ` +
195	        `or re-run the parent's agent by hand.`
196	      );
197	    case "parent-closed":
198	      return (
199	        `All sub-tasks of ${which} complete, but ${which} is closed, so no agent was started. ` +
200	        `The aggregation marker is already written, so no other caller will retry: ` +
201	        `reopen it and run the parent's agent by hand. Whoever asked for the run has been told on the issue.`
202	      );
203	    case "parent-busy":
204	      return (
205	        `All sub-tasks of ${which} complete, but ${which} already had an agent asked for on it, ` +
206	        `so no second one was started. The aggregation marker was removed, so closing a sub-issue ` +
207	        `again retries it once that run is done: the run that was asked for first is the one to ` +
208	        `wait for.`
209	      );
210	    case "undetermined":
211	      return `Did not aggregate #${closedNum}: ${result.why}. Nothing was dispatched, and nothing will retry.`;
212	  }
213	}
214	export async function dispatchOrchestratorIfReady(opts: DispatchGateOptions): Promise<DispatchGateResult> {
215	  const excludeNum = opts.exclude ? opts.closedNum : undefined;
216	  const count = () => countOpenSiblings({ repo: opts.repo, parent: opts.parent, exclude: excludeNum });
217	
218	  // `countOpenSiblings` throws when the sub-issue links could not be read, while every other
219	  // failure in this module is a return value. That exception used to escape the
220	  // gate entirely, and the two call sites were inconsistent about it -- one
221	  // wrapped the whole thing in try/catch and the other did not, which is not a
222	  // policy, it is one of them having remembered. Caught here so the gate has one
223	  // way of saying "could not tell".
224	  let remaining: number;
225	  try {
226	    remaining = count();
227	    if (opts.retry) {
228	      for (let attempt = 1; remaining > 0 && attempt < 4; attempt++) {
229	        await sleep(2000 * attempt);
230	        remaining = count();
231	      }
232	    }
233	  } catch (error) {
234	    const why = `could not count #${opts.parent}'s open sub-issues: ${(error as Error).message}`;
235	    console.error(why);
236	    return withNotice(opts, { kind: "undetermined", why });
237	  }
238	
239	  if (remaining > 0) {
240	    if (opts.progressMessage) {
241	      gh(
242	        "issue", "comment", String(opts.parent), "--repo", opts.repo,
243	        "--body", `${LLM_CONTEXT_TAG.write("exclude")}\n${SUB_RESULT_TAG.write(opts.closedNum)}\n${opts.progressMessage(remaining)}`,
244	      );
245	    }
246	    return { kind: "waiting", remaining };
247	  }
248	
249	  // The exit code matters here: this read IS the idempotency check. A failed one
250	  // returns no comments, the marker is not found, and both racing callers then
251	  // decide they are the first — which is the one thing the marker exists to
252	  // prevent. Not finding the marker and not being able to look are different
253	  // answers, and only one of them means "go ahead".
254	  //
255	  // `--paginate`, because `gh issue view --json comments` returns a bounded page: on
256	  // a parent with a long thread the marker written by the first racer is not in the
257	  // page the second racer reads, so the second concludes it is first and dispatches
258	  // again. A missed aggregation is recoverable by the other racer; a double dispatch
259	  // is not, which is why this read has to see the whole thread.
260	  //
261	  // `[.[].body]`, not `.[].body`: the bodies come back as a list, so the marker is
262	  // decided per body with `readProse` (#304) -- a comment quoting the marker inside
263	  // a fenced sample has not claimed anything, and an unclosed fence in one comment
264	  // cannot swallow the next comment's marker the way one `proseOnly` over the joined
