266	  const { code: commentsCode, stdout: commentsOut } = gh(
267	    "api", `repos/${opts.repo}/issues/${opts.parent}/comments`, "--paginate", "--jq", "[.[].body]",
268	  );
269	  if (commentsCode !== 0) {
