90	 *
91	 * Takes the text rather than fetching it. The doc comment here used to say
92	 * "Pure transform: returns an updated copy-in-place" -- which is two claims and
93	 * both were wrong. It was not pure: it called `gatherSubResults`, up to three
94	 * `gh` calls per sub-issue. And it is not a copy: it mutates `session.messages`
95	 * in place and returns the same object, which "copy-in-place" says in one
96	 * self-contradictory breath.
97	 *
98	 * The cost was that this rule -- find the last tool message, replace it, append
99	 * when there is none -- could not be tested without a fake `gh` on PATH. It is a
100	 * decision about a data structure and now reads like one.
101	 */
102	export function injectSummary(session: Session, summary: string): Session {
103	  const messages = session.messages ?? [];
104	  const lastToolIdx = findLastToolIndex(messages);
105	
106	  if (lastToolIdx === null) {
107	    console.error("No tool message found in session. Appending as user message.");
108	    messages.push({ role: "user", content: summary });
109	  } else {
110	    messages[lastToolIdx]!.content = summary;
111	  }
112	
113	  session.messages = messages;
114	  return session;
115	}
