2	/**
3	 * resolve_orchestrator_parent.ts — print a sub-issue's atomaton parent, for
4	 * a workflow step that needs the number in bash.
5	 *
6	 * The rule itself is `adapters/github/parent-issue.ts`. It used to be written out here as
7	 * well -- its own GraphQL query and its own body-tag read -- which made this the
8	 * only one of three call sites with the richer rule, for no reason anything
9	 * recorded. Both halves already existed in `lib/`.
10	 *
11	 * Usage: resolve_orchestrator_parent.ts --repo OWNER/REPO --sub N
12	 * Prints the resolved parent issue number, or nothing, to stdout.
13	 */
14	import { parseArgs } from "node:util";
15	import { parentIssueOf } from "../../adapters/github/parent-issue.ts";
16	import { defineScript } from "./lib/script-ref.ts";
17	
18	export interface ResolveOrchestratorParentArgs {
19	  repo: string;
20	  sub: string | number;
21	}
22	
23	export const ref = defineScript<ResolveOrchestratorParentArgs>(import.meta.url);
24	
25	function main(): void {
26	  const { values } = parseArgs({
27	    args: Bun.argv.slice(2),
28	    options: {
29	      repo: { type: "string" },
30	      sub: { type: "string" },
31	    },
32	  });
33	
34	  if (!values.repo || !values.sub) {
35	    console.error("usage: resolve_orchestrator_parent.ts --repo OWNER/REPO --sub N");
36	    process.exit(2);
37	  }
38	
39	  const found = parentIssueOf(values.repo, Number(values.sub));
40	  if (!found.known) {
41	    // Empty stdout, and a non-zero exit. The caller reads stdout to decide
42	    // whether there is a parent to aggregate, and "" is how "no parent" is
43	    // spelled -- so a failed read that printed "" would be indistinguishable
44	    // from a root issue, which is the whole class of defect this repository has
45	    // been working through.
46	    console.error(`::error::${found.why}`);
47	    process.exit(1);
48	  }
49	
50	  if (found.parent) console.error(`sub-issue #${values.sub} -> parent #${found.parent}`);
51	  console.log(found.parent || "");
52	}
53	
54	if (import.meta.main) main();

