124	export function resolveNotify(repo: string, number: number): string {
125	  // The walk is `parentChain`'s, so the depth limit and the cycle guard are the same
126	  // ones `workspace-scope.ts` uses. It used to be written out here with its own
127	  // `MAX_HOPS = 10`, which had drifted from the other copy's 6.
128	  //
129	  // One lookup per node: the same read answers "who to tell" and "what is the next
130	  // edge", so the walk does not ask GitHub twice for the same issue.
131	  const read = (current: number): { data: IssueLookup; parent: ParentIssue } => {
132	    const d = fetchIssueLookup(repo, current);
133	    const body = d.body ?? "";
134	    // Up one edge, and which edge depends on what this is. A pull request's link to
135	    // its issue is `atomaton:parent-issue`, which has no native equivalent that
136	    // survives — measured, and written down in `adapters/github/tags.ts`. An issue's link to its
137	    // parent is GitHub's own, and the tag that used to answer here is gone.
138	    const parent = d.is_pr ? PARENT_ISSUE_TAG.readProse(body) : nativeParentOf(repo, current);
139	    return { data: d, parent: parent === undefined ? { known: false, why: "no parent" } : { known: true, parent } };
140	  };
141	
142	  for (const hop of parentChain(number, read)) {
143	    const body = hop.data.body ?? "";
144	    const tagged = NOTIFY_TAG.readProse(body);
145	    if (tagged) return tagged;
146	    if (isHumanActor(hop.data.type) && hop.data.login) return hop.data.login;
147	  }
148	
149	  // Nothing in the thread said who to tell, so the owner is told. See
150	  // `repositoryOwner` for why that beats telling nobody.
151	  const owner = repositoryOwner(repo);
152	  if (owner) log(`no requester found for #${number}; falling back to the repository owner @${owner}`);
153	  return owner;
154	}

